@Test
public void testGetAndIncrement() {
    AtomicRangeInteger atomicI = new AtomicRangeInteger(0, 10);
    for (int i = 0; i < 10; i++) {
        Assert.assertEquals(i, atomicI.getAndIncrement());
    }
    Assert.assertEquals(0, atomicI.getAndIncrement());
    Assert.assertEquals(1, atomicI.get());
    Assert.assertEquals(1, atomicI.intValue());
    Assert.assertEquals(1, atomicI.longValue());
    Assert.assertEquals(1, (int) atomicI.floatValue());
    Assert.assertEquals(1, (int) atomicI.doubleValue());
}

@Test
public void testOneThreadPool() throws InterruptedException {
    BulkConsumePool pool = new BulkConsumePool("testPool", 1, 50);
    final ArrayList<Object> result1 = new ArrayList();
    Channels c1 = new Channels(2, 10, new SimpleRollingPartitioner(), BufferStrategy.OVERRIDE);
    pool.add("test", c1, new IConsumer() {

        @Override
        public void init() {
        }

        @Override
        public void consume(List data) {
            for (Object datum : data) {
                result1.add(datum);
            }
        }

        @Override
        public void onError(List data, Throwable t) {
        }

        @Override
        public void onExit() {
        }
    });
    pool.begin(c1);
    final ArrayList<Object> result2 = new ArrayList();
    Channels c2 = new Channels(2, 10, new SimpleRollingPartitioner(), BufferStrategy.OVERRIDE);
    pool.add("test2", c2, new IConsumer() {

        @Override
        public void init() {
        }

        @Override
        public void consume(List data) {
            for (Object datum : data) {
                result2.add(datum);
            }
        }

        @Override
        public void onError(List data, Throwable t) {
        }

        @Override
        public void onExit() {
        }
    });
    pool.begin(c2);
    c1.save(new Object());
    c1.save(new Object());
    c1.save(new Object());
    c1.save(new Object());
    c1.save(new Object());
    c2.save(new Object());
    c2.save(new Object());
    Thread.sleep(2000);
    Assert.assertEquals(5, result1.size());
    Assert.assertEquals(2, result2.size());
}

@Test
public void testBeginConsumeDriver() throws IllegalAccessException {
    Channels<SampleData> channels = new Channels<SampleData>(2, 100, new SimpleRollingPartitioner<SampleData>(), BufferStrategy.BLOCKING);
    ConsumeDriver<SampleData> pool = new ConsumeDriver<SampleData>("default", channels, new SampleConsumer(), 2, 20);
    pool.begin(channels);
    ConsumerThread[] threads = (ConsumerThread[]) MemberModifier.field(ConsumeDriver.class, "consumerThreads").get(pool);
    Assert.assertEquals(2, threads.length);
    Assert.assertTrue(threads[0].isAlive());
    Assert.assertTrue(threads[1].isAlive());
}

@Test
public void testCloseConsumeDriver() throws InterruptedException, IllegalAccessException {
    Channels<SampleData> channels = new Channels<SampleData>(2, 100, new SimpleRollingPartitioner<SampleData>(), BufferStrategy.BLOCKING);
    ConsumeDriver<SampleData> pool = new ConsumeDriver<SampleData>("default", channels, new SampleConsumer(), 2, 20);
    pool.begin(channels);
    Thread.sleep(5000);
    pool.close(channels);
    ConsumerThread[] threads = (ConsumerThread[]) MemberModifier.field(ConsumeDriver.class, "consumerThreads").get(pool);
    Assert.assertEquals(2, threads.length);
    Assert.assertFalse((Boolean) MemberModifier.field(ConsumerThread.class, "running").get(threads[0]));
    Assert.assertFalse((Boolean) MemberModifier.field(ConsumerThread.class, "running").get(threads[1]));
}

